#!/usr/bin/env bash
set -euo pipefail
mkdir -p out baseline-published data
exec > >(tee -a out/setup.log) 2>&1
# CPU/MPI baseline; record the discovered CUDA installation without using GPUs.
selected=''
for root in /usr/local/cuda /usr/lib/cuda; do
    if [[ -x "$root/bin/nvcc" && -f "$root/include/cuda_runtime.h" && -f "$root/lib64/libcudart.so" ]]; then selected="$root"; break; fi
done
if [[ -n "$selected" ]]; then
    ls "$selected/bin/nvcc" "$selected/include/cuda_runtime.h" "$selected/lib64/libcudart.so"
    printf 'export PATH=%q/bin:/usr/bin:/bin\nexport CUDAToolkit_ROOT=%q\nexport CUDACXX=%q/bin/nvcc\nexport CUDA_INCLUDE_DIR=%q/include\nexport CUDA_LIBRARY=%q/lib64/libcudart.so\n' "$selected" "$selected" "$selected" "$selected" "$selected" > baseline-published/cuda.env
else
    ls /usr/bin/nvcc /usr/include/cuda_runtime.h /usr/lib/x86_64-linux-gnu/libcudart.so
    cat > baseline-published/cuda.env <<'ENV'
export PATH=/usr/bin:/bin
export CUDACXX=/usr/bin/nvcc
export CUDA_INCLUDE_DIR=/usr/include
export CUDA_LIBRARY=/usr/lib/x86_64-linux-gnu/libcudart.so
ENV
fi
source baseline-published/cuda.env
packages=(git curl ca-certificates python3-venv build-essential libopenmpi-dev openmpi-bin libfftw3-dev libfftw3-single3 libhdf5-openmpi-dev libgl1 libopenblas0)
missing=()
for p in "${packages[@]}"; do
    if ! dpkg-query -W -f='${Status}' "$p" 2>/dev/null | grep -qx 'install ok installed'; then missing+=("$p"); fi
done
if ((${#missing[@]})); then
    sudo apt-get update
    for p in "${missing[@]}"; do
        apt-cache policy "$p"
        candidate=$(apt-cache policy "$p" | awk '/Candidate:/ {print $2}')
        [[ -n "$candidate" && "$candidate" != '(none)' ]] || { echo "No enabled apt candidate for $p"; exit 1; }
    done
    sudo apt-get install -y "${missing[@]}"
    for p in "${missing[@]}"; do echo "Installed package: $p"; dpkg-query -W "$p"; done
fi
if [[ ! -d baseline-published/pinder/.git ]]; then
    git clone https://github.com/pinder-org/pinder baseline-published/pinder
fi
git -C baseline-published/pinder checkout --detach ebeb28a2f8411363cef722b7d293c978f7442672
test "$(git -C baseline-published/pinder rev-parse HEAD)" = ebeb28a2f8411363cef722b7d293c978f7442672
test "$(git -C baseline-published/pinder rev-parse 'HEAD^{tree}')" = adc153de2eef1ac428c1136d609b30728c88cc7b
/usr/bin/python3 -m venv --system-site-packages baseline-published/venv
baseline-published/venv/bin/python - <<'PY'
import importlib.metadata as m
from pathlib import Path
try: version=m.version('torch')
except m.PackageNotFoundError: raise SystemExit('Stock torch missing; refusing replacement')
Path('baseline-published/stock.constraints').write_text('torch=='+version+'\n')
PY
# Keep build tooling in the venv: the stock setuptools/packaging combination
# cannot load the newest setuptools_scm/vcs-versioning entry point. These
# versions satisfy the pinned project's build-system requirements without
# introducing vcs-versioning or changing system packages or stock Torch.
baseline-published/venv/bin/python -m pip install -c baseline-published/stock.constraints \
    'setuptools==69.5.1' 'wheel==0.43.0' 'packaging==24.0' \
    'build==0.10.0' 'setuptools_scm[toml]==7.1.0'
# The inherited distro NetworkX uses np.int, removed in the baseline's NumPy.
# Install a compatible Python 3.10 version in the venv, preserving stock Torch
# and system packages. An explicit requirement overrides the inherited version.
baseline-published/venv/bin/python -m pip install --no-build-isolation \
    -c baseline-published/stock.constraints 'networkx==3.2.1' './baseline-published/pinder[data]'
baseline-published/venv/bin/python - <<'PY'
import networkx
import biotite.structure
from pinder.methods.preprocess import prepare_inference_inputs
print('Baseline dependency import check passed; NetworkX', networkx.__version__)
PY
baseline-published/venv/bin/python - <<'PY'
import base64,zlib,json,hashlib,urllib.request,time,concurrent.futures,zipfile,tarfile
from pathlib import Path
items=json.loads(zlib.decompress(base64.b64decode('')))
def fetch(x):
    name=x['name']
    if name=='frodock_distribution:unverified_mirror': name='frodock.tar.gz'
    dest=Path('data/2024-02')/name
    dest.parent.mkdir(parents=True,exist_ok=True)
    def valid(p):
        return p.exists() and p.stat().st_size==x['bytes'] and hashlib.sha256(p.read_bytes()).hexdigest()==x['sha256']
    if valid(dest): return
    tmp=dest.with_name(dest.name+'.part')
    for attempt in range(3):
        try:
            with urllib.request.urlopen(x['url'],timeout=120) as r, tmp.open('wb') as w:
                while b:=r.read(1024*1024): w.write(b)
            if not valid(tmp): raise ValueError('Checksum mismatch: '+name)
            tmp.replace(dest)
            return
        except Exception:
            if attempt==2: raise
            time.sleep(2)
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as pool:
    list(pool.map(fetch,items))
Path('data/inventory.json').write_text(json.dumps(items))
with zipfile.ZipFile('data/2024-02/test_set_pdbs.zip') as z: z.extractall('data/2024-02')
if not Path('baseline-published/frodock3_linux64').exists():
    with tarfile.open('data/2024-02/frodock.tar.gz') as t: t.extractall('baseline-published')
soap=Path('baseline-published/frodock3_linux64/bin/soap.bin')
if hashlib.sha256(soap.read_bytes()).hexdigest()!='791f31ec8ef1ef1466092b425638e926755519c9626f5678ca675ef6c76234fc':
    raise ValueError('soap.bin checksum mismatch')
PY
# Build the published GNU targets in compile_frodock.sh dependency order.
for target in libtools/Release_gcc libpdb/Release_gcc libpdb/Release2_gcc libvolume/Release_gcc libfrm/Release_gcc libbessel/Release_gcc libfrodock/Release_MPI_gcc libfrodockcluster/Relase_gcc libprotprot/Release_MPI_gcc libsas/Release_gcc frodock/Release_MPI_gcc frodockgrid/Release_MPI_GCC frodockcluster/Release_gcc frodockview/Release_gcc; do
    builddir="baseline-published/frodock3_linux64/src/$target"
    make -C "$builddir" clean
    make -C "$builddir" -j8
done
for binary in frodock_mpi_gcc frodockgrid_mpi_gcc frodockcluster_gcc frodockview_gcc; do
    test -x "baseline-published/frodock3_linux64/bin/$binary"
    ldd "baseline-published/frodock3_linux64/bin/$binary" > "out/ldd-$binary.log" 2>&1 || { grep -Eq "not a dynamic executable|statically linked" "out/ldd-$binary.log" || exit 1; }
    if grep -q 'not found' "out/ldd-$binary.log"; then cat "out/ldd-$binary.log"; exit 1; fi
done
export PINDER_BASE_DIR="$PWD/data"
export PINDER_RELEASE=2024-02
export PINDER_DATA_DIR="$PWD/data/2024-02"
export CUDA_VISIBLE_DEVICES=''
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
baseline-published/venv/bin/python - <<'PY'
import json
from pathlib import Path
import pandas as pd
from pinder.methods.preprocess import prepare_inference_inputs
idx=pd.read_parquet('data/2024-02/index.parquet')
s=idx[idx.pinder_s & idx.apo_R & idx.apo_L].sort_values('id')
ids=list(s.id)
if len(ids)!=93: raise ValueError('Invalid pinned input inventory: paired apo cases missing')
config=prepare_inference_inputs(Path('data/preprocessed'),ids=ids,pairs='apo')
config=sorted(config,key=lambda x:x['id'])
if [r['id'] for r in config]!=ids: raise ValueError('Preprocessing omitted inputs')
Path('data/cases.json').write_text(json.dumps(config,default=str,indent=2))
Path('data/counts.json').write_text(json.dumps({'pinder-s-size':int(idx.pinder_s.sum()),'pinder-s-paired-apo':len(ids)}))
PY
cat > baseline-published/run_baseline.py <<'PY'
import argparse, json, math, os, shutil, subprocess, time
from pathlib import Path
import pandas as pd
import biotite.structure.io as strucio
p=argparse.ArgumentParser()
p.add_argument('--cases',required=True)
p.add_argument('--out',required=True)
p.add_argument('--mpi-np',type=int,required=True)
p.add_argument('--n-solutions',type=int,required=True)
p.add_argument('--gpu-count',type=int,required=True)
p.add_argument('--input-id')
a=p.parse_args()
if (a.mpi_np,a.n_solutions,a.gpu_count)!=(8,100,0) or os.environ.get('CUDA_VISIBLE_DEVICES')!='':
    raise ValueError('Published configuration mismatch')
root=Path.cwd()
cases=json.loads(Path(a.cases).read_text())
if len(cases)!=93: raise ValueError('Missing fixed cases')
if a.input_id and a.input_id in {x['id'] for x in cases}:
    cases=[x for x in cases if x['id']==a.input_id]
out=Path(a.out); out.mkdir(parents=True,exist_ok=True)
run=out / ('run-'+str(time.time_ns())); run.mkdir()
print('CONFIG '+json.dumps({'mpi_np':a.mpi_np,'n_solutions':a.n_solutions,'gpu_count':a.gpu_count,'CUDA_VISIBLE_DEVICES':os.environ['CUDA_VISIBLE_DEVICES'],'cases':len(cases),'cwd':str(root),'OMP_NUM_THREADS':os.environ.get('OMP_NUM_THREADS')}),flush=True)
bindir=root/'baseline-published/frodock3_linux64/bin'
mpi=['/usr/bin/mpirun','-np',str(a.mpi_np),'--use-hwthread-cpus']
all_metrics=[]; total_wall=0.0
for case in cases:
    cid=case['id']; work=run/'scratch'/cid; work.mkdir(parents=True)
    dst=run/'results/frodock'/cid/'apo_decoys'; dst.mkdir(parents=True)
    start=time.perf_counter()
    shutil.copyfile(case['receptor'],work/'receptor.pdb')
    shutil.copyfile(case['ligand'],work/'ligand.pdb')
    grid=mpi+[str(bindir/'frodockgrid_mpi_gcc')]
    commands=[
      grid+['receptor.pdb','-o','receptor_W.mrc'],
      grid+['receptor.pdb','-o','receptor_E.mrc','-m','1','-t','A'],
      grid+['receptor.pdb','-o','receptor_DS.mrc','-m','3'],
      grid+['ligand.pdb','-o','ligand_DS.mrc','-m','3'],
      mpi+[str(bindir/'frodock_mpi_gcc'),'receptor_ASA.pdb','ligand_ASA.pdb','-w','receptor_W.mrc','-e','receptor_E.mrc','--th','10','-d','receptor_DS.mrc,ligand_DS.mrc','-t','A','-o','dock.dat','-s',str(bindir/'soap.bin')],
      [str(bindir/'frodockcluster_gcc'),'dock.dat','ligand.pdb','--nc',str(a.n_solutions),'-o','clust_dock.dat'],
      [str(bindir/'frodockview_gcc'),'clust_dock.dat','-r',f'1-{a.n_solutions}'],
      [str(bindir/'frodockview_gcc'),'clust_dock.dat','-r',f'1-{a.n_solutions}','-p','ligand.pdb']]
    for command in commands:
        print('COMMAND '+json.dumps(command),flush=True)
        subprocess.run(command,cwd=work,check=True)
    receptor=strucio.load_structure(str(work/'receptor.pdb'))
    for i in range(1,a.n_solutions+1):
        ligand=strucio.load_structure(str(work/f'ligand_{i}.pdb'))
        strucio.save_structure(str(dst/f'model_{i}.pdb'),receptor+ligand)
    # CPU/MPI processes have exited; no GPU work was launched.
    elapsed=time.perf_counter()-start; total_wall+=elapsed
    print('CASE_WALL '+json.dumps({'id':cid,'wall_s':elapsed}),flush=True)
# Invoke the published evaluator API, avoiding its interactive CLI confirmation.
from pinder.eval.dockq.method import MethodMetrics
mm=MethodMetrics(run/'results',parallel=True,allow_missing_systems=True,max_workers=8)
metrics=mm.metrics
metrics.to_csv(run/'frodock_metrics.csv',index=False)
mm.get_leaderboard_entry().to_csv(run/'frodock_leaderboard.csv',index=False)
selected=metrics[metrics.id.isin([c['id'] for c in cases]) & (metrics.monomer_name=='apo')].drop_duplicates(['id','rank'])
if len(selected)!=len(cases)*a.n_solutions: raise ValueError('Missing measured poses')
cols=['DockQ','iRMS','LRMS','Fnat']
if not all(math.isfinite(float(v)) for col in cols for v in selected[col]): raise ValueError('Invalid measured metric')
top=selected[selected['rank']==1].sort_values('id')
best=selected.groupby('id').DockQ.max()
counts=json.loads(Path('data/counts.json').read_text())
summary={'wall_s':total_wall,'gpu_count':0,'case_count':len(cases),'pose_count':len(selected),
 'DockQ':float(top.DockQ.mean()),'top1_DockQ':float(top.DockQ.mean()),'best100_DockQ':float(best.mean()),
 'iRMSD':float(top.iRMS.mean()),'LRMSD':float(top.LRMS.mean()),'fnat':float(top.Fnat.mean()),
 'acceptable_fraction':float((best>=0.23).sum()/len(cases)),
 'poses_per_s':len(selected)/total_wall,
 'anchors':dict(counts,**{'dockq-acceptable':float(top.iloc[0].DockQ)}),
 'run_dir':str(run)}
print('MEASUREMENT '+json.dumps(summary,allow_nan=False),flush=True)
PY
baseline-published/venv/bin/python -m pip freeze > out/installed-packages.txt
printf '%s\n' 'Setup complete: GNU MPI baseline installed; workload reserved for run_command.sh.'
